// Generated by philote from page /matches. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { matches } from "@/lib/api";
import { must } from "@/lib/backend";
import { readMatchCard } from "@/lib/reads";

import MatchCard from "@/components/common/match-card";

export const metadata: Metadata = { title: "Matches" };

export default function Page() {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl space-y-6">
                <h1 className="font-heading text-4xl">{"Matches"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Records />
                </Suspense>
            </div>
        </main>
    );
}

async function Records() {
    await connection();
    const records = await must(matches.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No matches yet."}</p>;
    }
    const items = await Promise.all(records.map(readMatchCard));
    return (
        <div className="grid gap-4 md:grid-cols-2">
            {items.map((item) => (
                <MatchCard key={item.match.id} {...item} />
            ))}
        </div>
    );
}
